using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default resolver so metadata is available for known types.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = JsonSerializerOptions.Default.TypeInfoResolver
};

// --- 1. Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> ---
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");

// Round-trip to prove it works
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"  Serialized: {json}");
var p = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"  Deserialized: {p}");

// --- 2. Probe without throwing: TryGetTypeInfo ---
// This succeeds (Person is resolvable)
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded — Kind={info!.Kind}");
else
    Console.WriteLine("\nTryGetTypeInfo(Person) returned false");

// Now use an options instance with NO resolver — metadata won't be available.
var empty = new JsonSerializerOptions { TypeInfoResolver = null };

if (empty.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("TryGetTypeInfo(Person) on empty options: found (unexpected)");
else
    Console.WriteLine("TryGetTypeInfo(Person) on empty options: not available — no exception thrown ✓");

